function cnField(rng){let w='';for(let r=0;r<3;r++)for(let k=0;k<26;k++){const x=k*14.5+rng()*8-4,y=356+r*26,h=34+rng()*16;w+=`<g class="wh" transform="translate(${x},${y})"><path d="M0,0 Q${2+rng()*3},${-h*.6} 0,${-h}" fill="none" stroke="${r?'#d9a826':'#e8bc38'}" stroke-width="3" stroke-linecap="round"/><ellipse cx="0" cy="${-h}" rx="3.500" ry="8" fill="${r?'#f2cc48':'#ffe06a'}" stroke="#8a6410" stroke-width="1"/></g>`}
  return `<path d="M0,300 Q90,262 190,292 T360,276 V440 H0 Z" fill="#9ccc5a"/><path d="M0,322 Q120,296 230,318 T360,306 V440 H0 Z" fill="#e2b93a"/><rect y="344" width="360" height="96" fill="#d2a52c"/><rect y="350" width="360" height="18" fill="#b98a3a" opacity=".55"/>${w}`}
